275: /// Starts the HTTP/WebSocket server listening on the configured socket address.
276: pub async fn start_server(config: ServerConfig) -> Result<(), ServerError> {
277:     let addr = format!("{}:{}", config.host, config.port);
278:     let listener = TcpListener::bind(&addr).await?;
279:     tracing::info!("OpenFlightReader server listening on http://{}", addr);
280: 
281:     let state = AppState::new(config);
282:     let app = build_app(state);
283: 
284:     axum::serve(listener, app)
285:         .with_graceful_shutdown(shutdown_signal())
