778: ### 6.1 Scrubber Message Protocol
779: Timeline scrubbing runs at 60 FPS. When the user interacts with the timeline slider on any client, all connected clients, maps, charts, and virtual instruments update instantaneously without latency.
780: 
781: ```rust
782: // src/routes/ws.rs
783: use axum::{
784:     extract::{
785:         ws::{Message, WebSocket, WebSocketUpgrade},
786:         State,
787:     },
788:     response::Response,
789: };
790: use futures_util::{SinkExt, StreamExt};
791: use serde::{Deserialize, Serialize};
792: use tokio::sync::broadcast;
793: use crate::state::AppState;
794: 
795: /// Bidirectional message protocol for 60 FPS timeline scrubber synchronization.
796: #[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
797: #[serde(tag = "type", content = "payload")]
798: pub enum WsScrubMessage {
799:     /// Dispatched when the user scrubs to a point index or during playback tick.
800:     Scrub {
801:         index: usize,
802:         timestamp_ms: i64,
803:     },
804:     /// Playback state changes (Play, Pause, Speed).
805:     Playback {
806:         playing: bool,
807:         speed: f64,
808:         current_index: usize,
809:     },
810:     /// Notification that a new flight dataset was ingested.
811:     DatasetLoaded {
812:         total_points: usize,
813:         duration_seconds: f64,
814:         log_type: String,
815:     },
816:     /// Heartbeat ping.
817:     Ping,
818:     /// Heartbeat pong.
819:     Pong,
820:     /// Error notification.
821:     Error {
822:         message: String,
823:     },
824: }
825: 
826: pub async fn ws_handler(
827:     ws: WebSocketUpgrade,
828:     State(state): State<AppState>,
829: ) -> Response {
830:     ws.on_upgrade(move |socket| handle_ws_socket(socket, state))
831: }
832: 
833: async fn handle_ws_socket(socket: WebSocket, state: AppState) {
834:     let (mut ws_sender, mut ws_receiver) = socket.split();
835:     let mut broadcast_rx = state.ws_broadcaster.subscribe();
836: 
837:     // Spawn bidirectional relay task
838:     let mut send_task = tokio::spawn(async move {
839:         while let Ok(msg) = broadcast_rx.recv().await {
840:             if let Ok(json_str) = serde_json::to_string(&msg) {
841:                 if ws_sender.send(Message::Text(json_str)).await.is_err() {
842:                     break;
843:                 }
844:             }
845:         }
846:     });
847: 
848:     let broadcaster = state.ws_broadcaster.clone();
849:     let mut recv_task = tokio::spawn(async move {
850:         while let Some(Ok(message)) = ws_receiver.next().await {
851:             match message {
852:                 Message::Text(text) => {
853:                     if let Ok(cmd) = serde_json::from_str::<WsScrubMessage>(&text) {
854:                         match cmd {
855:                             WsScrubMessage::Scrub { .. } | WsScrubMessage::Playback { .. } => {
856:                                 let _ = broadcaster.send(cmd);
857:                             }
858:                             WsScrubMessage::Ping => {
859:                                 let _ = broadcaster.send(WsScrubMessage::Pong);
860:                             }
861:                             _ => {}
862:                         }
863:                     }
864:                 }
865:                 Message::Close(_) => break,
866:                 _ => {}
867:             }
868:         }
869:     });
870: 
871:     // Terminate cleanly when either side disconnects
872:     tokio::select! {
873:         _ = (&mut send_task) => recv_task.abort(),
874:         _ = (&mut recv_task) => send_task.abort(),
875:     };
876: }
877: ```
