904: ) -> Result<FlightDataset, ExportError> {
905:     if buffer.is_empty() {
906:         return Ok(FlightDataset::new());
907:     }
908: 
909:     // Check for DAT magic 0x55
910:     if buffer[0] == flightreader_core::dat::DAT_MAGIC {
911:         let mut aggregator = TelemetryAggregator::new(egm);
912:         aggregator.metadata.log_type = "DJI_DAT".to_string();
913:         let iter = flightreader_core::dat::DatFrameIterator::new(buffer);
914:         for frame in iter.flatten() {
915:             let _ = aggregator.process_dat_frame(&frame);
916:         }
917: 
918:         Ok(aggregator.finish())
919:     } else {
920:         // Parse as DJI .txt
921:         let header = flightreader_core::txt::TxtHeader::parse(buffer)?;
922:         let mut aggregator = TelemetryAggregator::new(egm).with_version(header.version);
923:         aggregator.metadata.log_type = format!("DJI_TXT_V{}", header.version);
