/**
 * OpenFlightReader — Autonomous 2D Canvas Trajectory Renderer
 * 100% Offline Air-Gapped Flight Path Visualization
 */
(function (global) {
    'use strict';

    const R_EARTH = 6378137.0; // WGS84 equatorial radius in meters

    class CanvasRenderer {
        constructor(canvasId) {
            this.canvas = document.getElementById(canvasId);
            this.ctx = this.canvas.getContext('2d');
            this.points = null;
            this.metadata = null;
            this.metricPoints = []; // [{ x: meters, y: meters, alt: meters }]
            this.originLat = 0;
            this.originLon = 0;

            // Viewport & Camera State
            this.panX = 0; // meters
            this.panY = 0; // meters
            this.scale = 1.0; // pixels per meter
            this.isDragging = false;
            this.dragStartX = 0;
            this.dragStartY = 0;

            this.initEvents();
            this.resize();
        }

        initEvents() {
            window.addEventListener('resize', () => this.resize());

            this.canvas.addEventListener('mousedown', (e) => {
                this.isDragging = true;
                this.dragStartX = e.clientX;
                this.dragStartY = e.clientY;
            });

            window.addEventListener('mousemove', (e) => {
                if (!this.isDragging) return;
                const dx = e.clientX - this.dragStartX;
                const dy = e.clientY - this.dragStartY;
                this.dragStartX = e.clientX;
                this.dragStartY = e.clientY;

                this.panX -= dx / this.scale;
                this.panY += dy / this.scale;
                this.render();
            });

            window.addEventListener('mouseup', () => {
                this.isDragging = false;
            });

            this.canvas.addEventListener('wheel', (e) => {
                e.preventDefault();
                const zoomFactor = e.deltaY < 0 ? 1.15 : 0.85;
                this.scale *= zoomFactor;
                this.render();
            });
        }

        resize() {
            if (!this.canvas.parentElement) return;
            const rect = this.canvas.parentElement.getBoundingClientRect();
            const dpr = window.devicePixelRatio || 1;
            this.canvas.width = rect.width * dpr;
            this.canvas.height = rect.height * dpr;
            this.ctx.setTransform(1, 0, 0, 1, 0, 0);
            this.ctx.scale(dpr, dpr);
            this.width = rect.width;
            this.height = rect.height;
            this.render();
        }

        loadDataset(points, metadata) {
            this.points = points;
            this.metadata = metadata;
            this.metricPoints = [];

            const latArr = points ? (points.latitudes || points.lat) : null;
            const lonArr = points ? (points.longitudes || points.lon) : null;
            const altArr = points ? (points.altitudes_agl || points.alt_agl) : null;

            if (!latArr || latArr.length === 0) return;

            // Use Takeoff or centroid as origin
            this.originLat = (metadata && metadata.home_latitude) ? metadata.home_latitude : latArr[0];
            this.originLon = (metadata && metadata.home_longitude) ? metadata.home_longitude : lonArr[0];
            const cosLat = Math.cos(this.originLat * Math.PI / 180.0);

            let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;

            for (let i = 0; i < latArr.length; i++) {
                const lat = latArr[i];
                const lon = lonArr[i];
                if (lat === 0 && lon === 0) {
                    this.metricPoints.push(null);
                    continue;
                }
                const x = (lon - this.originLon) * (Math.PI / 180.0) * R_EARTH * cosLat;
                const y = (lat - this.originLat) * (Math.PI / 180.0) * R_EARTH;
                const alt = altArr ? altArr[i] : 0;

                this.metricPoints.push({ x, y, alt });

                minX = Math.min(minX, x);
                maxX = Math.max(maxX, x);
                minY = Math.min(minY, y);
                maxY = Math.max(maxY, y);
            }

            // Auto-fit bounds
            const spanX = Math.max(10, maxX - minX);
            const spanY = Math.max(10, maxY - minY);
            this.panX = (minX + maxX) / 2;
            this.panY = (minY + maxY) / 2;
            const availableW = Math.max(100, this.width - 80);
            const availableH = Math.max(100, this.height - 80);
            this.scale = Math.min(availableW / spanX, availableH / spanY);
            this.render();
        }

        renderFrame(currentIndex) {
            this.currentIndex = currentIndex;
            this.render();
        }

        centerOnIndex(index) {
            if (!this.metricPoints[index]) return;
            this.panX = this.metricPoints[index].x;
            this.panY = this.metricPoints[index].y;
            this.render();
        }

        render() {
            const ctx = this.ctx;
            if (!ctx || !this.width || !this.height) return;
            ctx.clearRect(0, 0, this.width, this.height);

            // 1. Radar Grid Background
            this.drawGrid(ctx);

            if (!this.metricPoints || this.metricPoints.length === 0) {
                this.drawEmptyMessage(ctx);
                return;
            }

            // 2. Trajectory Polyline
            this.drawTrajectory(ctx);

            // 3. Home Point Marker
            this.drawHomePoint(ctx);

            // 4. Current Aircraft Symbol
            if (this.currentIndex !== undefined && this.metricPoints[this.currentIndex]) {
                const cur = this.metricPoints[this.currentIndex];
                const headingArr = this.points.headings_deg || this.points.heading || this.points.yaws_deg || this.points.yaw;
                const heading = headingArr ? headingArr[this.currentIndex] : 0;
                this.drawAircraft(ctx, cur.x, cur.y, heading || 0);
            }

            // 5. Compass Rose & Metric Scale Bar
            this.drawScaleBar(ctx);
            this.drawCompass(ctx);
        }

        drawGrid(ctx) {
            ctx.save();
            ctx.fillStyle = '#050811';
            ctx.fillRect(0, 0, this.width, this.height);

            // Dynamic grid spacing
            const targetPixelSpacing = 80;
            const rawMeters = targetPixelSpacing / (this.scale || 1.0);
            const magnitude = Math.pow(10, Math.floor(Math.log10(Math.max(1e-3, rawMeters))));
            let gridStepMeters = magnitude;
            if (rawMeters / magnitude > 5) gridStepMeters = 5 * magnitude;
            else if (rawMeters / magnitude > 2) gridStepMeters = 2 * magnitude;

            const gridStepPixels = gridStepMeters * this.scale;
            const startX = (this.width / 2 - this.panX * this.scale) % gridStepPixels;
            const startY = (this.height / 2 + this.panY * this.scale) % gridStepPixels;

            ctx.strokeStyle = '#121824';
            ctx.lineWidth = 1;

            ctx.beginPath();
            for (let x = startX; x < this.width; x += gridStepPixels) {
                ctx.moveTo(x, 0);
                ctx.lineTo(x, this.height);
            }
            for (let y = startY; y < this.height; y += gridStepPixels) {
                ctx.moveTo(0, y);
                ctx.lineTo(this.width, y);
            }
            ctx.stroke();

            // Home Axes
            const cx = this.width / 2 - this.panX * this.scale;
            const cy = this.height / 2 + this.panY * this.scale;
            ctx.strokeStyle = '#1b2436';
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(cx, 0); ctx.lineTo(cx, this.height);
            ctx.moveTo(0, cy); ctx.lineTo(this.width, cy);
            ctx.stroke();

            ctx.restore();
        }

        drawTrajectory(ctx) {
            ctx.save();
            ctx.lineWidth = 2.5;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';

            const pts = this.metricPoints;
            const curIdx = this.currentIndex || 0;

            for (let i = 1; i < pts.length; i++) {
                const p0 = pts[i - 1];
                const p1 = pts[i];
                if (!p0 || !p1) continue;

                const u0 = this.width / 2 + (p0.x - this.panX) * this.scale;
                const v0 = this.height / 2 - (p0.y - this.panY) * this.scale;
                const u1 = this.width / 2 + (p1.x - this.panX) * this.scale;
                const v1 = this.height / 2 - (p1.y - this.panY) * this.scale;

                // Color based on altitude
                const alt = p1.alt;
                if (alt < 15) ctx.strokeStyle = '#00e676';
                else if (alt < 60) ctx.strokeStyle = '#00b0ff';
                else if (alt < 120) ctx.strokeStyle = '#ffd600';
                else ctx.strokeStyle = '#ff1744';

                // Future path is dimmed
                ctx.globalAlpha = i <= curIdx ? 0.95 : 0.2;

                ctx.beginPath();
                ctx.moveTo(u0, v0);
                ctx.lineTo(u1, v1);
                ctx.stroke();
            }

            ctx.restore();
        }

        drawHomePoint(ctx) {
            const u = this.width / 2 + (0 - this.panX) * this.scale;
            const v = this.height / 2 - (0 - this.panY) * this.scale;

