            ctx.fillStyle = '#121824';
            ctx.strokeStyle = '#273248';
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.arc(cx, cy, this.gimbalRadius, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();

