            ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx - this.gimbalRadius, cy);
            ctx.lineTo(cx + this.gimbalRadius, cy);
            ctx.moveTo(cx, cy - this.gimbalRadius);
            ctx.lineTo(cx, cy + this.gimbalRadius);
            ctx.stroke();

            // Concentric 50% circle
            ctx.beginPath();
            ctx.arc(cx, cy, this.gimbalRadius * 0.5, 0, Math.PI * 2);
            ctx.stroke();

            ctx.restore();
