            const cellCount = validCells.length;

            if (this.voltsElem) this.voltsElem.textContent = ((packVoltageMv || 0) / 1000.0).toFixed(2) + ' V';
            if (this.ampsElem) this.ampsElem.textContent = (currentA || 0).toFixed(1) + ' A';
            if (this.tempBadge) this.tempBadge.textContent = `${(tempC || 0).toFixed(1)}°C`;

            // Calculate Delta V
            let deltaMv = 0;
            if (cellCount > 1) {
                const maxV = Math.max(...validCells);
                const minV = Math.min(...validCells);
                deltaMv = maxV - minV;
            }

            if (this.deltaElem) {
                this.deltaElem.textContent = `${deltaMv} mV`;
                this.deltaElem.className = 'stat-val ' + (deltaMv <= 30 ? 'stat-nominal' : (deltaMv <= 80 ? 'stat-warning' : 'stat-danger'));
            }

            // Rebuild DOM bars if cell count changed
            if (this.container && cellCount !== this.renderedCellCount) {
                this.buildBars(cellCount);
                this.renderedCellCount = cellCount;
            }

            // Update individual cell bars
            for (let i = 0; i < cellCount; i++) {
                const mv = validCells[i];
                const volts = (mv / 1000.0);
                const fillRatio = Math.max(0.05, Math.min(1.0, (mv - 3200) / (4350 - 3200)));

                const fillBar = document.getElementById(`cell-fill-${i}`);
                const textElem = document.getElementById(`cell-txt-${i}`);

                if (fillBar) {
                    fillBar.style.height = `${Math.round(fillRatio * 100)}%`;
                    fillBar.style.backgroundColor = this.getCellColor(volts);
                }
                if (textElem) {
                    textElem.textContent = volts.toFixed(2);
                }
            }
        }

        getCellColor(volts) {
            if (volts >= 4.10) return '#00e676';
            if (volts >= 3.80) return '#22c55e';
            if (volts >= 3.65) return '#ffd600';
            if (volts >= 3.45) return '#ff9100';
            return '#ff1744';
        }

        buildBars(count) {
            if (!this.container) return;
            this.container.innerHTML = '';
            for (let i = 0; i < count; i++) {
                const wrapper = document.createElement('div');
                wrapper.className = 'cell-bar-wrapper';

                const txt = document.createElement('span');
                txt.className = 'cell-volts-text';
                txt.id = `cell-txt-${i}`;
                txt.textContent = '0.00';

                const track = document.createElement('div');
                track.className = 'cell-bar-track';

                const fill = document.createElement('div');
                fill.className = 'cell-bar-fill';
                fill.id = `cell-fill-${i}`;
                fill.style.height = '50%';
                fill.style.backgroundColor = '#00e676';

                track.appendChild(fill);

                const idx = document.createElement('span');
                idx.className = 'cell-idx-text';
                idx.textContent = `C${i + 1}`;

