        const nextIndex = Math.min(state.pointCount - 1, state.currentIndex + Math.max(1, Math.round(pointsToAdvance)));

        if (nextIndex >= state.pointCount - 1) {
            seekToIndex(state.pointCount - 1, 'playback');
            togglePlayPause();
            return;
        }

        seekToIndex(nextIndex, 'playback');
        requestAnimationFrame(playbackLoop);
    }

    function recenterAircraft() {
        if (!state.points || state.pointCount === 0) return;
        const latArr = state.points.latitudes || state.points.lat || [];
        const lonArr = state.points.longitudes || state.points.lon || [];
        const lat = latArr[state.currentIndex];
        const lon = lonArr[state.currentIndex];
        if (state.renderMode === 'leaflet' && leafletMap && (lat !== 0 || lon !== 0)) {
            leafletMap.panTo([lat, lon]);
        } else if (state.renderMode === 'canvas' && canvasRenderer) {
            canvasRenderer.centerOnIndex(state.currentIndex);
        }
    }

    // WebSocket Synchronization
    function initWebSocket() {
        const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
        const wsUrl = `${protocol}//${window.location.host}/api/v1/ws`;

        try {
            state.ws = new WebSocket(wsUrl);

            state.ws.onopen = () => {
                state.wsConnected = true;
                if (elements.wsStatus) {
                    elements.wsStatus.textContent = 'Synced';
                    elements.wsStatus.className = 'status-indicator status-online';
                }
            };

            state.ws.onmessage = (event) => {
                try {
                    const msg = JSON.parse(event.data);
                    if ((msg.type === 'sync' || msg.type === 'frame') && msg.index !== undefined && msg.index !== state.currentIndex) {
                        seekToIndex(msg.index, 'remote');
                    } else if (msg.type === 'dataset_loaded') {
                        fetchFlightData();
                    } else if (msg.type === 'playback') {
                        if (msg.playing !== undefined && msg.playing !== state.isPlaying) {
                            state.isPlaying = msg.playing;
                            if (elements.btnPlayPause) elements.btnPlayPause.textContent = state.isPlaying ? '⏸' : '▶';
                            if (state.isPlaying) {
                                state.lastFrameTime = performance.now();
                                requestAnimationFrame(playbackLoop);
                            }
                        }
                        if (msg.current_index !== undefined) {
                            seekToIndex(msg.current_index, 'remote');
                        }
                    }
                } catch (e) {}
            };

            state.ws.onclose = () => {
                state.wsConnected = false;
                if (elements.wsStatus) {
                    elements.wsStatus.textContent = 'Local';
                    elements.wsStatus.className = 'status-indicator status-offline';
                }
                setTimeout(initWebSocket, 3000); // Reconnect loop
            };

            state.ws.onerror = () => {
                if (state.ws) state.ws.close();
            };
        } catch (e) {
            if (elements.wsStatus) {
                elements.wsStatus.textContent = 'Local';
                elements.wsStatus.className = 'status-indicator status-offline';
            }
        }
    }

    function sendWsMessage(msg) {
        if (state.ws && state.ws.readyState === WebSocket.OPEN) {
            state.ws.send(JSON.stringify(msg));
        }
    }

    // File Upload Handling
    function handleFileUpload(e) {
        if (e.target.files && e.target.files.length > 0) {
            uploadLogFile(e.target.files[0]);
        }
    }

    async function uploadLogFile(file) {
        const formData = new FormData();
        formData.append('file', file);

        try {
            if (elements.hudAlertText) elements.hudAlertText.textContent = `Uploading and parsing ${file.name}...`;
            if (elements.hudAlert) elements.hudAlert.style.display = 'block';

            const res = await fetch('/api/v1/upload', {
                method: 'POST',
                body: formData
            });

            if (res.ok) {
                if (elements.hudAlertText) elements.hudAlertText.textContent = `Successfully decoded ${file.name}`;
                setTimeout(() => { if (elements.hudAlert) elements.hudAlert.style.display = 'none'; }, 2000);
                fetchFlightData();
            } else {
                if (elements.hudAlertText) elements.hudAlertText.textContent = `Upload failed: ${res.statusText}`;
            }
        } catch (err) {
            if (elements.hudAlertText) elements.hudAlertText.textContent = `Upload error: ${err.message}`;
        }
    }

    function formatDuration(seconds) {
        if (seconds == null || isNaN(seconds)) return '00:00.0';
        const mins = Math.floor(seconds / 60);
        const secs = (seconds % 60).toFixed(1);
        return `${mins.toString().padStart(2, '0')}:${secs.padStart(4, '0')}`;
    }
})();

//! Server error definitions and HTTP response mappings.

use axum::{
    http::StatusCode,
    response::{IntoResponse, Response},
    Json,
};
use serde_json::json;
use thiserror::Error;

/// Central error type for `flightreader-server` operations.
#[derive(Debug, Error)]
pub enum ServerError {
    /// Filesystem or network I/O error.
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),

    /// Core binary flight log decoding error.
    #[error("Core log parsing error: {0}")]
    Core(#[from] flightreader_core::FlightReaderError),

    /// Telemetry aggregation or export processing error.
    #[error("Export aggregation error: {0}")]
    Export(#[from] flightreader_export::ExportError),

    /// JSON serialization or deserialization error.
    #[error("JSON error: {0}")]
    Json(#[from] serde_json::Error),

    /// Resource not found error.
    #[error("Not found: {0}")]
    NotFound(String),

    /// Client bad request or malformed payload.
    #[error("Bad request: {0}")]
    BadRequest(String),

    /// Multipart form decoding failure.
    #[error("Invalid multipart payload: {0}")]
    Multipart(String),

    /// Internal unrecoverable server error.
    #[error("Internal server error: {0}")]
    Internal(String),
}

impl IntoResponse for ServerError {
    fn into_response(self) -> Response {
        let (status, error_code, message) = match &self {
            ServerError::NotFound(msg) => (StatusCode::NOT_FOUND, "NOT_FOUND", msg.clone()),
            ServerError::BadRequest(msg) | ServerError::Multipart(msg) => {
                (StatusCode::BAD_REQUEST, "BAD_REQUEST", msg.clone())
            }
            ServerError::Core(err) => (
                StatusCode::BAD_REQUEST,
                "CORRUPT_LOG_PAYLOAD",
                err.to_string(),
            ),
            ServerError::Export(err) => (
                StatusCode::BAD_REQUEST,
                "AGGREGATION_FAILED",
                err.to_string(),
            ),
            ServerError::Io(err) => (
                StatusCode::INTERNAL_SERVER_ERROR,
                "IO_ERROR",
                err.to_string(),
            ),
            ServerError::Json(err) => (
                StatusCode::INTERNAL_SERVER_ERROR,
                "SERIALIZATION_ERROR",
                err.to_string(),
            ),
            ServerError::Internal(msg) => (
                StatusCode::INTERNAL_SERVER_ERROR,
                "INTERNAL_ERROR",
                msg.clone(),
            ),
        };

        let body = Json(json!({
            "error": message,
            "code": error_code,
            "status": status.as_u16(),
        }));

        (status, body).into_response()
    }
}

//! Shared application state across HTTP handlers and WebSocket sessions.

use std::sync::Arc;
use std::time::Instant;
use tokio::sync::{broadcast, RwLock};

use flightreader_export::model::FlightDataset;

use crate::routes::ws::WsServerMessage;
use crate::ServerConfig;

/// Shared application state across all request handlers and WebSocket connections.
#[derive(Clone)]
pub struct AppState {
    /// In-memory active flight dataset, protected by an asynchronous read-write lock.
    pub dataset: Arc<RwLock<Option<FlightDataset>>>,
    /// Immutable server launch configuration.
    pub config: Arc<ServerConfig>,
    /// Broadcast channel for real-time timeline scrubber synchronization (capacity: 128).
    pub ws_broadcaster: broadcast::Sender<WsServerMessage>,
    /// Alias for test and caller convenience.
    pub ws_broadcast: broadcast::Sender<WsServerMessage>,
    /// Timestamp when server was started.
    pub start_time: Instant,
}

impl AppState {
    /// Creates a new `AppState` instance initialized from the given configuration.
    pub fn new(config: ServerConfig) -> Self {
        let (ws_broadcaster, _) = broadcast::channel(128);
        let dataset = Arc::new(RwLock::new(config.initial_dataset.clone()));
        let ws_broadcast = ws_broadcaster.clone();

        Self {
            dataset,
            config: Arc::new(config),
            ws_broadcaster,
            ws_broadcast,
            start_time: Instant::now(),
        }
    }

    /// Creates an empty `AppState` with default server configuration.
    pub fn new_empty() -> Self {
        Self::new(ServerConfig::default())
    }

    /// Creates an `AppState` pre-populated with a flight dataset.
    pub fn new_with_dataset(dataset: FlightDataset) -> Self {
        let mut config = ServerConfig::default();
        config.initial_dataset = Some(dataset);
        Self::new(config)
    }

    /// Convenience helper to set the active dataset and broadcast an update event.
    pub async fn set_dataset(&self, new_dataset: FlightDataset) {
        let count = new_dataset.points.len();
        let duration = new_dataset.metadata.duration_seconds;
        let log_type = new_dataset.metadata.log_type.clone();

        {
            let mut lock = self.dataset.write().await;
            *lock = Some(new_dataset);
        }

        let _ = self.ws_broadcaster.send(WsServerMessage::DatasetLoaded {
            total_points: count,
            duration_seconds: duration,
            log_type,
        });
    }

    /// Checks if a dataset is currently loaded.
    pub async fn has_dataset(&self) -> bool {
        self.dataset.read().await.is_some()
    }
}

//! Embedded offline static asset serving with air-gapped Content-Security-Policy.

use axum::{
    http::{header, HeaderValue, StatusCode, Uri},
    response::{IntoResponse, Response},
};
use rust_embed::RustEmbed;

/// Static assets embedded directly into the server binary at compile time.
#[derive(RustEmbed)]
#[folder = "assets/"]
pub struct EmbeddedAssets;

/// Authoritative strict air-gapped Content-Security-Policy header value.
pub const CSP_VALUE: &str = "default-src 'self' 'unsafe-inline' data:; connect-src 'self' ws:; img-src 'self' data: blob:; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; object-src 'none'; base-uri 'self'";

/// Serves compile-time embedded frontend assets from memory.
pub async fn static_handler(uri: Uri) -> Response {
    let raw_path = uri.path();

    // Directory traversal security check
    if raw_path.contains("..") || raw_path.contains("%2e") || raw_path.contains("%2E") {
        return (StatusCode::NOT_FOUND, "Not Found").into_response();
    }

    let mut path = raw_path.trim_start_matches('/').to_string();
    if path.is_empty() {
        path = "index.html".to_string();
    }

    match EmbeddedAssets::get(&path) {
        Some(content) => {
            let mime = if path.ends_with(".js") {
                "application/javascript; charset=utf-8".to_string()
            } else if path.ends_with(".css") {
                "text/css; charset=utf-8".to_string()
            } else if path.ends_with(".html") {
                "text/html; charset=utf-8".to_string()
            } else {
                mime_guess::from_path(&path)
                    .first_or_octet_stream()
                    .to_string()
            };

            let mut response = (StatusCode::OK, content.data).into_response();
            let headers = response.headers_mut();

            // MIME type
            if let Ok(val) = HeaderValue::from_str(&mime) {
                headers.insert(header::CONTENT_TYPE, val);
            }

            // Air-Gap Strict Content-Security-Policy
            headers.insert(
                header::HeaderName::from_static("content-security-policy"),
                HeaderValue::from_static(CSP_VALUE),
            );

            // Security Hardening Headers
            headers.insert(
                header::X_CONTENT_TYPE_OPTIONS,
                HeaderValue::from_static("nosniff"),
            );
            headers.insert(header::X_FRAME_OPTIONS, HeaderValue::from_static("DENY"));
            headers.insert(
                header::HeaderName::from_static("referrer-policy"),
                HeaderValue::from_static("no-referrer"),
            );

            // Caching
            let cache_control = if path == "index.html" {
                "no-cache, must-revalidate"
            } else {
                "public, max-age=3600"
            };
            headers.insert(
                header::CACHE_CONTROL,
                HeaderValue::from_static(cache_control),
            );

            response
        }
        None => {
            // SPA fallback: paths without extension serve index.html
            if !path.contains('.') {
                if let Some(index) = EmbeddedAssets::get("index.html") {
                    let mut response = (StatusCode::OK, index.data).into_response();
                    let headers = response.headers_mut();
                    headers.insert(
                        header::CONTENT_TYPE,
                        HeaderValue::from_static("text/html; charset=utf-8"),
                    );
                    headers.insert(
                        header::HeaderName::from_static("content-security-policy"),
                        HeaderValue::from_static(CSP_VALUE),
                    );
                    headers.insert(
                        header::CACHE_CONTROL,
                        HeaderValue::from_static("no-cache, must-revalidate"),
                    );
                    return response;
                }
            }

            (StatusCode::NOT_FOUND, "404 Not Found").into_response()
        }
    }
}

//! Health check endpoint for server liveness and telemetry presence.

use axum::{extract::State, Json};
use serde::Serialize;

use crate::state::AppState;

/// Health status response payload.
#[derive(Debug, Serialize)]
pub struct HealthResponse {
    /// Overall service status string ("ok").
    pub status: &'static str,
    /// Service name identifier.
    pub service: &'static str,
    /// Application name identifier.
    pub app: &'static str,
    /// Crate semantic version string.
    pub version: &'static str,
    /// Whether an active flight dataset is loaded in memory.
    pub has_flight_data: bool,
    /// Total count of telemetry points currently loaded.
    pub point_count: usize,
    /// Server uptime in seconds.
    pub uptime_secs: u64,
    /// Server uptime in seconds (alias).
    pub uptime_seconds: u64,
}

/// Handler for `GET /api/v1/health`.
pub async fn health_check(State(state): State<AppState>) -> Json<HealthResponse> {
    let (has_flight_data, point_count) = {
        let lock = state.dataset.read().await;
        match &*lock {
            Some(ds) => (true, ds.points.len()),
            None => (false, 0),
        }
    };

    let elapsed = state.start_time.elapsed().as_secs();

    Json(HealthResponse {
        status: "ok",
        service: "flightreader-server",
        app: "flightreader-server",
        version: env!("CARGO_PKG_VERSION"),
        has_flight_data,
        point_count,
        uptime_secs: elapsed,
        uptime_seconds: elapsed,
    })
}

//! Flight metadata and 60 FPS columnar telemetry points endpoints.

use axum::{
    extract::{Query, State},
    Json,
};
use serde::{Deserialize, Serialize};

use flightreader_export::filter::{filter_dataset, TimeBound, TimeFilter};
use flightreader_export::model::{FlightEvent, FlightMetadata};

use crate::error::ServerError;
