/// 2D / 3D geographic and vertical bounding box of the flight trajectory.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FlightBounds {
    /// Minimum geodetic latitude in degrees.
    pub min_latitude: f64,
    /// Maximum geodetic latitude in degrees.
    pub max_latitude: f64,
    /// Minimum geodetic longitude in degrees.
    pub min_longitude: f64,
    /// Maximum geodetic longitude in degrees.
    pub max_longitude: f64,
    /// Minimum altitude MSL in meters.
    pub min_altitude_msl: f64,
    /// Maximum altitude MSL in meters.
    pub max_altitude_msl: f64,
}

/// Flight metadata and session summary response payload.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FlightInfoResponse {
    /// Whether a flight dataset is actively loaded.
    pub loaded: bool,
    /// Session overview metadata.
    pub metadata: FlightMetadata,
    /// Landmark milestone and safety events.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub events: Option<Vec<FlightEvent>>,
    /// Trajectory spatial bounding box.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub bounds: Option<FlightBounds>,
}

/// Handler for `GET /api/v1/flight/info`.
pub async fn get_flight_info(
    State(state): State<AppState>,
) -> Result<Json<FlightInfoResponse>, ServerError> {
    let lock = state.dataset.read().await;

    match &*lock {
        Some(dataset) => {
            let mut min_lat = 90.0f64;
            let mut max_lat = -90.0f64;
            let mut min_lon = 180.0f64;
            let mut max_lon = -180.0f64;
            let mut min_alt = f64::INFINITY;
            let mut max_alt = f64::NEG_INFINITY;
            let mut valid_coords = 0usize;

            for pt in &dataset.points {
                if pt.latitude != 0.0 || pt.longitude != 0.0 {
                    valid_coords += 1;
                    min_lat = min_lat.min(pt.latitude);
                    max_lat = max_lat.max(pt.latitude);
                    min_lon = min_lon.min(pt.longitude);
                    max_lon = max_lon.max(pt.longitude);
                    min_alt = min_alt.min(pt.altitude_msl);
                    max_alt = max_alt.max(pt.altitude_msl);
                }
            }

            let bounds = if valid_coords > 0 {
                Some(FlightBounds {
                    min_latitude: min_lat,
                    max_latitude: max_lat,
                    min_longitude: min_lon,
                    max_longitude: max_lon,
                    min_altitude_msl: min_alt,
                    max_altitude_msl: max_alt,
                })
            } else {
                None
            };

            Ok(Json(FlightInfoResponse {
                loaded: true,
                metadata: dataset.metadata.clone(),
                events: Some(dataset.events.clone()),
                bounds,
            }))
        }
        None => {
            let mut default_meta = FlightMetadata::default();
            default_meta.log_type = "NONE".to_string();
            default_meta.version = 0;
            default_meta.total_records = 0;
            default_meta.duration_seconds = 0.0;

            Ok(Json(FlightInfoResponse {
                loaded: false,
                metadata: default_meta,
                events: None,
                bounds: None,
            }))
        }
    }
}

