/// Handler for `GET /api/v1/flight/points`.
pub async fn get_flight_points(
    State(state): State<AppState>,
    Query(query): Query<PointsQuery>,
) -> Result<Json<ColumnarPointsResponse>, ServerError> {
    let lock = state.dataset.read().await;

    let dataset = match &*lock {
        Some(ds) => ds,
        None => {
            return Ok(Json(ColumnarPointsResponse::with_capacity(0)));
        }
    };

    // Validate query parameters
    if let (Some(s), Some(e)) = (query.start, query.end) {
        if s > e {
            return Err(ServerError::BadRequest(
                "Invalid time window: start time cannot exceed end time".to_string(),
            ));
        }
    }

    if let Some(r) = query.rate {
        if r <= 0.0 {
            return Err(ServerError::BadRequest(
                "Invalid decimation rate: must be strictly positive".to_string(),
            ));
        }
    }

    // Apply filtering or decimation if requested
    let filtered_dataset;
    let points = if query.start.is_some() || query.end.is_some() || query.rate.is_some() {
        let time_filter = if query.start.is_some() || query.end.is_some() {
            Some(TimeFilter {
                start: query.start.map(TimeBound::ElapsedSeconds),
                end: query.end.map(TimeBound::ElapsedSeconds),
            })
        } else {
            None
        };

        filtered_dataset = filter_dataset(dataset, time_filter.as_ref(), query.rate)?;
        &filtered_dataset.points
    } else {
        &dataset.points
    };

    let cap = points.len();
    let mut resp = ColumnarPointsResponse::with_capacity(cap);

    for pt in points {
        resp.indices.push(pt.index);
        resp.timestamp_utc_ms.push(pt.timestamp_utc_ms);
        resp.elapsed_s.push(pt.elapsed_s);
        resp.fly_time_s.push(pt.fly_time_s);
        resp.latitudes.push(pt.latitude);
        resp.longitudes.push(pt.longitude);
        resp.altitudes_msl.push(pt.altitude_msl);
        resp.altitudes_agl.push(pt.altitude_agl);
        resp.altitudes_baro.push(pt.altitude_baro);
        resp.ground_speeds_mps.push(pt.ground_speed_mps);
        resp.speeds_3d_mps.push(pt.speed_3d_mps);
        resp.climb_rates_mps.push(pt.climb_rate_mps);
        resp.vel_n.push(pt.vel_n);
        resp.vel_e.push(pt.vel_e);
        resp.vel_d.push(pt.vel_d);
        resp.courses_deg.push(pt.course_deg);
        resp.pitches_deg.push(pt.pitch_deg);
        resp.rolls_deg.push(pt.roll_deg);
        resp.yaws_deg.push(pt.yaw_deg);
        resp.headings_deg.push(pt.heading_deg);
        resp.gimbal_pitches_deg.push(pt.gimbal_pitch_deg);
        resp.gimbal_rolls_deg.push(pt.gimbal_roll_deg);
        resp.gimbal_yaws_deg.push(pt.gimbal_yaw_deg);
        resp.rc_ailerons.push(pt.rc_aileron);
        resp.rc_elevators.push(pt.rc_elevator);
        resp.rc_throttles.push(pt.rc_throttle);
        resp.rc_rudders.push(pt.rc_rudder);
        resp.battery_pcts.push(pt.battery_pct);
        resp.battery_voltages_mv.push(pt.battery_voltage_mv);
        resp.battery_temps_c.push(pt.battery_temp_c);
        resp.cell_voltages_mv.push(pt.cell_voltages_mv.clone());
        resp.cell_deviations_mv.push(pt.cell_deviation_mv);
        resp.gps_satellites.push(pt.gps_satellites);
        resp.flight_modes.push(pt.flight_mode.clone());
        resp.is_motor_on.push(pt.is_motor_on);
    }

    resp.count = resp.indices.len();
    Ok(Json(resp))
}

//! Flight log upload endpoint supporting multipart forms and raw binary streams.

use axum::{
    extract::{Request, State},
    http::header::CONTENT_TYPE,
    Json,
};
use serde::Serialize;

use flightreader_export::model::FlightMetadata;

use crate::error::ServerError;
use crate::state::AppState;

/// Upload success response payload.
#[derive(Debug, Serialize)]
pub struct UploadResponse {
    /// Status indicator ("success").
    pub status: &'static str,
    /// Informational message.
    pub message: String,
    /// Detected log format identifier.
    pub log_type: String,
    /// Total count of synchronized telemetry points extracted.
    pub records_count: usize,
    /// Total recording duration in seconds.
    pub duration_seconds: f64,
    /// Extracted flight metadata.
    pub metadata: FlightMetadata,
}

/// Handler for `POST /api/v1/upload`.
pub async fn upload_flight_log(
    State(state): State<AppState>,
    req: Request,
) -> Result<Json<UploadResponse>, ServerError> {
    let content_type = req
        .headers()
        .get(CONTENT_TYPE)
        .and_then(|v| v.to_str().ok())
        .unwrap_or("")
        .to_string();

    let raw_bytes: Vec<u8> = if content_type.starts_with("multipart/form-data") {
        let mut multipart = axum::extract::Multipart::from_request(req, &state)
            .await
            .map_err(|e| ServerError::Multipart(e.to_string()))?;

        let mut extracted = Vec::new();
        while let Some(field) = multipart
            .next_field()
            .await
            .map_err(|e| ServerError::Multipart(e.to_string()))?
        {
            let data = field
                .bytes()
                .await
                .map_err(|e| ServerError::Multipart(e.to_string()))?;
            if !data.is_empty() {
                extracted = data.to_vec();
                break;
            }
        }

        if extracted.is_empty() {
            return Err(ServerError::BadRequest(
                "No valid file payload found in multipart upload".to_string(),
            ));
        }
        extracted
    } else {
        // Raw binary direct payload
        let body_bytes = axum::body::to_bytes(req.into_body(), 256 * 1024 * 1024)
            .await
            .map_err(|e| ServerError::BadRequest(e.to_string()))?;
        body_bytes.to_vec()
    };

    if raw_bytes.is_empty() {
        return Err(ServerError::BadRequest(
            "Uploaded flight log payload is empty".to_string(),
        ));
    }

    // Minimum header length validation
    if raw_bytes[0] == flightreader_core::dat::DAT_MAGIC {
        if raw_bytes.len() < 9 {
            return Err(ServerError::BadRequest(
                "Truncated .DAT header: expected at least 9 bytes".to_string(),
            ));
        }
    } else if raw_bytes.len() < 100 {
        return Err(ServerError::BadRequest(
            "Truncated DJI .txt header: expected at least 100 bytes".to_string(),
        ));
    }

    // Ingest and aggregate via flightreader-export engine
    let dataset = flightreader_export::aggregate_buffer(&raw_bytes, None)
        .map_err(ServerError::Export)?;

    let records_count = dataset.points.len();
    let duration_seconds = dataset.metadata.duration_seconds;
    let log_type = dataset.metadata.log_type.clone();
    let metadata = dataset.metadata.clone();

    // Atomically swap dataset in AppState and notify WebSocket subscribers
    state.set_dataset(dataset).await;

    Ok(Json(UploadResponse {
        status: "success",
        message: format!(
            "Successfully parsed and loaded {} ({} telemetry points)",
            log_type, records_count
        ),
        log_type,
        records_count,
        duration_seconds,
        metadata,
    }))
}

