/// Client-to-server WebSocket messages.
#[derive(Debug, Clone, Deserialize, PartialEq)]
#[serde(tag = "type")]
pub enum WsClientMessage {
    /// Client requests seek to point index.
    #[serde(rename = "seek")]
    Seek {
        /// Target sample index.
        index: usize,
    },
    /// Client requests seek to elapsed seconds.
    #[serde(rename = "seek_time")]
    SeekTime {
        /// Target elapsed time in seconds.
        elapsed_s: f64,
    },
    /// Scrubber slider movement.
    #[serde(rename = "scrub")]
    Scrub {
        /// Target sample index.
        index: usize,
        /// Optional client timestamp in milliseconds.
        #[serde(default)]
        timestamp_ms: Option<i64>,
    },
    /// Playback state change.
    #[serde(rename = "playback")]
    Playback {
        /// Whether playback is running.
        playing: bool,
        /// Playback speed multiplier.
        speed: f64,
        /// Current playback index.
        current_index: usize,
    },
    /// Heartbeat ping.
    #[serde(rename = "ping")]
    Ping,
}

/// A synchronized telemetry playback frame sent to connected clients.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PlaybackFrame {
    /// Sample index.
    pub index: usize,
    /// UTC timestamp in epoch milliseconds.
    pub timestamp_utc_ms: i64,
    /// Elapsed seconds from log start.
    pub elapsed_s: f64,
    /// Airborne flight timer in seconds.
    pub fly_time_s: f64,
    /// WGS84 Geodetic Latitude in decimal degrees.
    pub latitude: f64,
    /// WGS84 Geodetic Longitude in decimal degrees.
    pub longitude: f64,
    /// Altitude MSL in meters.
    pub altitude_msl: f64,
    /// Altitude AGL in meters.
    pub altitude_agl: f64,
    /// Horizontal ground speed in m/s.
    pub ground_speed_mps: f64,
    /// Aircraft pitch angle in degrees.
    pub pitch_deg: f64,
    /// Aircraft roll angle in degrees.
    pub roll_deg: f64,
    /// Aircraft yaw angle in degrees.
    pub yaw_deg: f64,
    /// Compass heading in degrees.
    pub heading_deg: f64,
    /// Gimbal pitch angle in degrees.
    pub gimbal_pitch_deg: f64,
    /// Normalized aileron stick deflection.
    pub rc_aileron: f64,
    /// Normalized elevator stick deflection.
    pub rc_elevator: f64,
    /// Normalized throttle stick deflection.
    pub rc_throttle: f64,
