/// Server-to-client WebSocket messages.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(tag = "type")]
pub enum WsServerMessage {
    /// Synchronized telemetry frame broadcast.
    #[serde(rename = "frame")]
    Frame(Box<PlaybackFrame>),
    /// Playback state synchronization.
    #[serde(rename = "playback")]
    Playback {
        /// Whether playback is running.
        playing: bool,
        /// Playback speed multiplier.
        speed: f64,
        /// Current playback index.
        current_index: usize,
    },
    /// Notification that a new dataset was ingested.
    #[serde(rename = "dataset_loaded")]
    DatasetLoaded {
        /// Total telemetry points in dataset.
        total_points: usize,
        /// Total recording duration in seconds.
        duration_seconds: f64,
        /// Log format identifier.
        log_type: String,
    },
    /// Heartbeat pong.
    #[serde(rename = "pong")]
    Pong,
    /// Error notification.
    #[serde(rename = "error")]
    Error {
        /// Descriptive error text.
        message: String,
    },
}

/// Convenience alias for the server broadcast scrub message.
pub type WsScrubMessage = WsServerMessage;

/// Handler for `GET /api/v1/ws`.
pub async fn ws_handler(ws: WebSocketUpgrade, State(state): State<AppState>) -> Response {
    ws.on_upgrade(move |socket| handle_ws_socket(socket, state))
}

async fn handle_ws_socket(socket: WebSocket, state: AppState) {
    let (mut ws_sender, mut ws_receiver) = socket.split();
    let mut broadcast_rx = state.ws_broadcaster.subscribe();

    // Outbound task: forward broadcast messages to this WebSocket client
    let mut send_task = tokio::spawn(async move {
        while let Ok(msg) = broadcast_rx.recv().await {
            if let Ok(json_str) = serde_json::to_string(&msg) {
                if ws_sender.send(Message::Text(json_str)).await.is_err() {
                    break;
                }
            }
        }
    });

    // Inbound task: receive client commands and process seeks/pings
    let broadcaster = state.ws_broadcaster.clone();
    let state_clone = state.clone();

    let mut recv_task = tokio::spawn(async move {
        while let Some(Ok(message)) = ws_receiver.next().await {
            match message {
                Message::Text(text) => {
                    // Try parsing as structured WsClientMessage
                    if let Ok(cmd) = serde_json::from_str::<WsClientMessage>(&text) {
                        match cmd {
                            WsClientMessage::Seek { index } | WsClientMessage::Scrub { index, .. } => {
                                handle_seek(index, &state_clone, &broadcaster).await;
                            }
                            WsClientMessage::SeekTime { elapsed_s } => {
                                handle_seek_time(elapsed_s, &state_clone, &broadcaster).await;
                            }
                            WsClientMessage::Playback {
                                playing,
                                speed,
                                current_index,
                            } => {
                                let _ = broadcaster.send(WsServerMessage::Playback {
                                    playing,
                                    speed,
                                    current_index,
                                });
                            }
                            WsClientMessage::Ping => {
                                let _ = broadcaster.send(WsServerMessage::Pong);
                            }
                        }
                    } else if let Ok(val) = serde_json::from_str::<serde_json::Value>(&text) {
                        // Resilient fallback for alternative JSON shapes
                        if let Some(action) = val.get("action").and_then(|v| v.as_str()) {
                            match action {
                                "seek" => {
                                    if let Some(idx) = val.get("index").and_then(|v| v.as_u64()) {
                                        handle_seek(idx as usize, &state_clone, &broadcaster).await;
                                    }
                                }
                                "play" | "pause" => {
                                    let playing = action == "play";
                                    let speed = val.get("speed").and_then(|v| v.as_f64()).unwrap_or(1.0);
                                    let idx = val.get("index").and_then(|v| v.as_u64()).unwrap_or(0) as usize;
                                    let _ = broadcaster.send(WsServerMessage::Playback {
                                        playing,
                                        speed,
                                        current_index: idx,
                                    });
                                }
                                _ => {}
                            }
                        }
                    }
                }
                Message::Close(_) => break,
                _ => {}
            }
        }
    });

    // Terminate when either task finishes
    tokio::select! {
        _ = (&mut send_task) => recv_task.abort(),
        _ = (&mut recv_task) => send_task.abort(),
    };
}

async fn handle_seek(
    requested_idx: usize,
    state: &AppState,
    broadcaster: &tokio::sync::broadcast::Sender<WsServerMessage>,
) {
    let lock = state.dataset.read().await;
    match &*lock {
        Some(ds) if !ds.points.is_empty() => {
            let total = ds.points.len();
            let clamped_idx = requested_idx.min(total - 1);
            let pt = &ds.points[clamped_idx];

            let frame = PlaybackFrame {
                index: clamped_idx,
                timestamp_utc_ms: pt.timestamp_utc_ms,
                elapsed_s: pt.elapsed_s,
                fly_time_s: pt.fly_time_s,
                latitude: pt.latitude,
                longitude: pt.longitude,
                altitude_msl: pt.altitude_msl,
                altitude_agl: pt.altitude_agl,
                ground_speed_mps: pt.ground_speed_mps,
                pitch_deg: pt.pitch_deg,
                roll_deg: pt.roll_deg,
                yaw_deg: pt.yaw_deg,
                heading_deg: pt.heading_deg,
                gimbal_pitch_deg: pt.gimbal_pitch_deg,
                rc_aileron: pt.rc_aileron,
                rc_elevator: pt.rc_elevator,
                rc_throttle: pt.rc_throttle,
                rc_rudder: pt.rc_rudder,
                battery_pct: pt.battery_pct,
                battery_voltage_mv: pt.battery_voltage_mv,
                cell_voltages_mv: pt.cell_voltages_mv.clone(),
                gps_satellites: pt.gps_satellites,
                flight_mode: pt.flight_mode.clone(),
                is_motor_on: pt.is_motor_on,
            };

            let _ = broadcaster.send(WsServerMessage::Frame(Box::new(frame)));
        }
        _ => {
            let _ = broadcaster.send(WsServerMessage::Error {
                message: "No flight log loaded".to_string(),
            });
        }
    }
}

async fn handle_seek_time(
    elapsed_s: f64,
    state: &AppState,
    broadcaster: &tokio::sync::broadcast::Sender<WsServerMessage>,
) {
    let lock = state.dataset.read().await;
    match &*lock {
        Some(ds) if !ds.points.is_empty() => {
            let clamped_s = elapsed_s.max(0.0);
            let mut best_idx = 0;
            let mut best_diff = f64::INFINITY;

            for (i, pt) in ds.points.iter().enumerate() {
                let diff = (pt.elapsed_s - clamped_s).abs();
                if diff < best_diff {
                    best_diff = diff;
                    best_idx = i;
                }
            }

            let pt = &ds.points[best_idx];
            let frame = PlaybackFrame {
                index: best_idx,
                timestamp_utc_ms: pt.timestamp_utc_ms,
                elapsed_s: pt.elapsed_s,
                fly_time_s: pt.fly_time_s,
                latitude: pt.latitude,
                longitude: pt.longitude,
                altitude_msl: pt.altitude_msl,
                altitude_agl: pt.altitude_agl,
                ground_speed_mps: pt.ground_speed_mps,
                pitch_deg: pt.pitch_deg,
                roll_deg: pt.roll_deg,
                yaw_deg: pt.yaw_deg,
                heading_deg: pt.heading_deg,
                gimbal_pitch_deg: pt.gimbal_pitch_deg,
                rc_aileron: pt.rc_aileron,
                rc_elevator: pt.rc_elevator,
                rc_throttle: pt.rc_throttle,
                rc_rudder: pt.rc_rudder,
                battery_pct: pt.battery_pct,
                battery_voltage_mv: pt.battery_voltage_mv,
                cell_voltages_mv: pt.cell_voltages_mv.clone(),
                gps_satellites: pt.gps_satellites,
                flight_mode: pt.flight_mode.clone(),
                is_motor_on: pt.is_motor_on,
            };

            let _ = broadcaster.send(WsServerMessage::Frame(Box::new(frame)));
        }
        _ => {
            let _ = broadcaster.send(WsServerMessage::Error {
                message: "No flight log loaded".to_string(),
            });
        }
    }
}

//! Route aggregation and Axum router construction.

pub mod flight;
pub mod health;
pub mod upload;
pub mod ws;

use axum::{
    extract::DefaultBodyLimit,
    http::{header, HeaderValue},
    middleware::{self, Next},
    response::Response,
    routing::{get, post},
    Router,
};
use tower_http::cors::{Any, CorsLayer};
use tower_http::trace::TraceLayer;

use crate::assets;
use crate::state::AppState;

/// Injects strict air-gapped Content-Security-Policy and security headers into all responses.
async fn security_headers_middleware(request: axum::extract::Request, next: Next) -> Response {
    let mut response = next.run(request).await;
    let headers = response.headers_mut();

    headers.insert(
        header::HeaderName::from_static("content-security-policy"),
        HeaderValue::from_static(assets::CSP_VALUE),
    );
    headers.insert(
        header::X_CONTENT_TYPE_OPTIONS,
        HeaderValue::from_static("nosniff"),
    );
    headers.insert(header::X_FRAME_OPTIONS, HeaderValue::from_static("DENY"));
    headers.insert(
        header::HeaderName::from_static("referrer-policy"),
        HeaderValue::from_static("no-referrer"),
    );

    response
}

/// Builds the complete Axum router configured with middleware, API routes, and static asset fallback.
pub fn build_app(state: AppState) -> Router {
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    // 256 MB upload limit to support high-frequency blackbox .DAT files
    let body_limit = DefaultBodyLimit::max(256 * 1024 * 1024);

    Router::new()
        // API v1 Endpoints
        .route("/api/v1/health", get(health::health_check))
        .route("/api/v1/flight/info", get(flight::get_flight_info))
        .route("/api/v1/flight/points", get(flight::get_flight_points))
        .route("/api/v1/upload", post(upload::upload_flight_log))
        .route("/api/v1/ws", get(ws::ws_handler))
        // Static assets and fallback
        .fallback(assets::static_handler)
        // Layer middleware
        .layer(middleware::from_fn(security_headers_middleware))
        .layer(body_limit)
        .layer(cors)
        .layer(TraceLayer::new_for_http())
        .with_state(state)
}

//! OpenFlightReader Offline Local Web Daemon & Telemetry Dashboard (`flightreader-server`).
//!
//! Provides a lightweight, 100% offline, air-gapped Axum HTTP and WebSocket daemon
//! delivering interactive flight telemetry visualization, synchronized 60 FPS timeline
//! scrubbing, virtual aeronautical instruments (ADI, Mode 2 RC sticks, 12-cell battery heatmap),
//! and autonomous 2D Canvas trajectory fallback without external cloud dependencies.

#![deny(unsafe_code)]
#![warn(missing_docs)]

pub mod assets;
pub mod error;
pub mod routes;
pub mod state;

use std::path::PathBuf;
use flightreader_export::model::FlightDataset;

pub use error::ServerError;
pub use routes::build_app;
pub use routes::ws::{PlaybackFrame, WsClientMessage, WsScrubMessage, WsServerMessage};
pub use state::AppState;

/// Configuration parameters for launching the offline Axum server.
#[derive(Debug, Clone)]
pub struct ServerConfig {
    /// IP address or interface to bind (e.g., "127.0.0.1" for localhost, "0.0.0.0" for LAN).
    pub host: String,
    /// TCP port to bind (default: 8080).
    pub port: u16,
    /// Whether to automatically open the default web browser upon launch.
    pub open_browser: bool,
    /// Optional path to an MBTiles vector/raster basemap SQLite archive.
    pub mbtiles_path: Option<PathBuf>,
    /// Optional directory containing extracted offline map tiles (`{z}/{x}/{y}.png`).
    pub tile_dir: Option<PathBuf>,
    /// Pre-loaded flight dataset (e.g. provided via CLI argument `flightreader serve <FILE>`).
    pub initial_dataset: Option<FlightDataset>,
}

impl Default for ServerConfig {
    fn default() -> Self {
        Self {
            host: "127.0.0.1".to_string(),
            port: 8080,
            open_browser: false,
            mbtiles_path: None,
            tile_dir: None,
            initial_dataset: None,
        }
    }
}

/// Starts the HTTP and WebSocket server with default state initialized from config.
pub async fn start_server(config: ServerConfig) -> Result<(), ServerError> {
    let state = AppState::new(config.clone());
    start_server_with_state(config, state).await
}

/// Starts the HTTP and WebSocket server with explicit pre-existing shared state.
pub async fn start_server_with_state(
    config: ServerConfig,
    state: AppState,
) -> Result<(), ServerError> {
    let addr = format!("{}:{}", config.host, config.port);
    let listener = tokio::net::TcpListener::bind(&addr).await?;
    tracing::info!("OpenFlightReader server listening on http://{}", addr);

    let app = build_app(state);

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await?;

    tracing::info!("Server shut down gracefully");
    Ok(())
}

async fn shutdown_signal() {
    let _ = tokio::signal::ctrl_c().await;
    tracing::info!("Received Ctrl-C signal, initiating graceful shutdown...");
}

