//! Comprehensive integration test suite for `flightreader-server`.
//!
//! Validates:
//! 1. REST API endpoints (`/api/v1/health`, `/api/v1/flight/info`, `/api/v1/flight/points`).
//! 2. Columnar 60 FPS telemetry serialization and length parity across all 35+ fields.
//! 3. Time filtering and rate decimation query parameters.
//! 4. Flight log upload handling (both raw binary stream and multipart form-data) with validation.
//! 5. Static asset serving from compile-time embedded memory with strict MIME types.
//! 6. Strict air-gapped Content-Security-Policy (CSP) and security hardening headers.
//! 7. Path traversal attack rejection.
//! 8. WebSocket timeline scrubber bidirectional synchronization (seek, scrub, playback, ping/pong).
//! 9. Automated static audit of embedded UI assets ensuring ZERO external cloud or CDN dependencies.

use axum::body::Body;
use axum::http::{header, Request, StatusCode};
use futures_util::{SinkExt, StreamExt};
use http_body_util::BodyExt;
use serde_json::Value;
use tokio_tungstenite::connect_async;
use tokio_tungstenite::tungstenite::Message;
use tower::ServiceExt;

use flightreader_export::model::{
    FlightDataset, FlightEvent, FlightEventType, FlightMetadata, TelemetryPoint,
};
use flightreader_server::assets::{EmbeddedAssets, CSP_VALUE};
use flightreader_server::routes::build_app;
use flightreader_server::routes::flight::{ColumnarPointsResponse, FlightInfoResponse};
use flightreader_server::routes::health::HealthResponse;
use flightreader_server::routes::ws::WsServerMessage;
use flightreader_server::state::AppState;

/// Shared test fixture generating a canonical 600-point (60-second @ 10 Hz) flight dataset.
fn mock_flight_dataset() -> FlightDataset {
    let base_lat = 47.606212;
    let base_lon = -122.332145;
    let takeoff_alt_msl = 125.4;
    let target_alt_agl = 98.4;
    let cruise_speed_mps = 12.5;
    let base_time_ms = 1_729_000_000_000i64;

    let mut points = Vec::with_capacity(600);

    for i in 0..600 {
        let elapsed_s = i as f64 * 0.1;
        let fly_time_s = if i < 30 { 0.0 } else { elapsed_s - 3.0 };
        let is_motor_on = (30..570).contains(&i);

        let (agl, vel_d) = if i < 30 {
            (0.0, 0.0)
        } else if i < 150 {
            let frac = (i - 30) as f64 / 120.0;
            (frac * target_alt_agl, -0.82)
        } else if i < 450 {
            (target_alt_agl, 0.0)
        } else if i < 570 {
            let frac = 1.0 - (i - 450) as f64 / 120.0;
            (frac * target_alt_agl, 0.82)
        } else {
            (0.0, 0.0)
        };

        let alt_msl = takeoff_alt_msl + agl;

        let yaw_deg = if i < 150 {
            0.0
        } else if i < 300 {
            (i - 150) as f64 * (90.0 / 150.0)
        } else {
            90.0
        };

        let (vel_n, vel_e, h_speed) = if is_motor_on && (150..450).contains(&i) {
            let rad = yaw_deg.to_radians();
            (cruise_speed_mps * rad.cos(), cruise_speed_mps * rad.sin(), cruise_speed_mps)
        } else if is_motor_on {
            (1.5, 0.0, 1.5)
        } else {
            (0.0, 0.0, 0.0)
        };

        let speed_3d = (vel_n * vel_n + vel_e * vel_e + vel_d * vel_d).sqrt();
        let lat = base_lat + (i as f64 * 0.000001);
        let lon = base_lon + (i as f64 * 0.0000015);
        let timestamp_utc_ms = base_time_ms + (elapsed_s * 1000.0).round() as i64;
        let timestamp_iso8601 = format!("2026-10-28T12:00:{:02}.000Z", i / 10);

        let frac_time = i as f64 / 600.0;
        let battery_pct = (98.0 - frac_time * 13.0).round() as u8;
        let pack_v = 16.4 - frac_time * 1.6;
        let cell_v_mv = ((pack_v / 4.0) * 1000.0).round() as u16;

        let pt = TelemetryPoint {
            index: i,
            timestamp_utc_ms,
            timestamp_iso8601,
            elapsed_s,
            fly_time_s,
            latitude: lat,
            longitude: lon,
            altitude_msl: alt_msl,
            altitude_agl: agl,
            altitude_baro: agl,
            vps_height_m: if agl < 3.0 { Some(agl) } else { None },
            ground_speed_mps: h_speed,
            speed_3d_mps: speed_3d,
            climb_rate_mps: -vel_d,
            vel_n,
            vel_e,
            vel_d,
            course_deg: yaw_deg,
            pitch_deg: if vel_n > 5.0 { -12.4 } else { 0.0 },
            roll_deg: if yaw_deg > 0.0 && yaw_deg < 90.0 { 5.2 } else { 0.0 },
            yaw_deg,
            heading_deg: yaw_deg,
            gimbal_pitch_deg: -45.0,
            gimbal_roll_deg: 0.0,
            gimbal_yaw_deg: 0.0,
            gimbal_mode: "Follow Yaw".to_string(),
            rc_aileron: 0.10,
            rc_elevator: 0.30,
            rc_throttle: 0.50,
            rc_rudder: 0.0,
            rc_mode_switch: "P".to_string(),
            rc_signal_quality: 100,
            battery_pct,
            battery_voltage_mv: (pack_v * 1000.0).round() as u32,
            battery_temp_c: 28.5 + frac_time * 6.0,
            battery_current_a: Some(8.45),
            cell_voltages_mv: vec![cell_v_mv, cell_v_mv - 2, cell_v_mv + 1, cell_v_mv],
            cell_deviation_mv: 3,
            gps_satellites: 18,
            gps_level: 5,
            flight_mode: "P-GPS".to_string(),
            ground_state: if is_motor_on { "Airborne".to_string() } else { "OnGround".to_string() },
            is_motor_on,
            is_failsafe_active: false,
            app_warning: None,
            app_tip: None,
        };
        points.push(pt);
    }

    let metadata = FlightMetadata {
        log_type: "DJI_TXT_V12".to_string(),
        version: 12,
        app_type: Some("DJIFly".to_string()),
        app_version: Some("1.12.8".to_string()),
        drone_type: Some(77),
        aircraft_model: Some("DJI Mavic 3".to_string()),
        aircraft_name: Some("SkyMaster-01".to_string()),
        aircraft_serial: Some("1581F45X210001".to_string()),
        camera_serial: Some("320F98B2".to_string()),
        rc_serial: Some("412A87C1".to_string()),
        battery_serial: Some("089P32D1".to_string()),
        start_time_utc: Some(points[0].timestamp_iso8601.clone()),
        start_time_utc_ms: base_time_ms,
        end_time_utc: Some(points.last().unwrap().timestamp_iso8601.clone()),
        duration_seconds: 59.9,
        flight_duration_seconds: 54.0,
        total_distance_meters: 650.0,
        max_altitude_agl_m: target_alt_agl,
        max_altitude_msl_m: takeoff_alt_msl + target_alt_agl,
        takeoff_elevation_msl_m: takeoff_alt_msl,
        max_horizontal_speed_mps: cruise_speed_mps,
        max_vertical_speed_mps: 0.82,
        max_descent_speed_mps: 0.82,
        home_latitude: Some(base_lat),
        home_longitude: Some(base_lon),
        home_altitude_msl: Some(takeoff_alt_msl),
        rth_altitude_m: Some(30.0),
        total_records: 600,
        photos_count: Some(4),
        video_time_seconds: Some(45),
    };

    let events = vec![
        FlightEvent {
            timestamp_utc_ms: base_time_ms,
            elapsed_s: 0.0,
            flight_time_s: 0.0,
            event_type: FlightEventType::HomeRecorded,
            description: "Home Point Calibrated".to_string(),
            message: "Home Point recorded at GPS fix".to_string(),
            latitude: Some(base_lat),
            longitude: Some(base_lon),
            altitude_msl: Some(takeoff_alt_msl),
        },
        FlightEvent {
            timestamp_utc_ms: base_time_ms + 3000,
            elapsed_s: 3.0,
            flight_time_s: 0.0,
            event_type: FlightEventType::Takeoff,
            description: "Propulsion Motors Spun Up".to_string(),
            message: "Aircraft airborne".to_string(),
            latitude: Some(base_lat),
            longitude: Some(base_lon),
            altitude_msl: Some(takeoff_alt_msl),
        },
    ];

    FlightDataset {
        metadata,
        points,
        events,
    }
}

