#[tokio::test]
async fn test_health_endpoint_returns_ok_uninitialized() {
    let state = AppState::new_empty();
    let app = build_app(state);

    let req = Request::builder()
        .method("GET")
        .uri("/api/v1/health")
        .body(Body::empty())
        .unwrap();

    let res = app.oneshot(req).await.unwrap();
    assert_eq!(res.status(), StatusCode::OK);
    assert!(res
        .headers()
        .get(header::CONTENT_TYPE)
        .unwrap()
        .to_str()
        .unwrap()
        .contains("application/json"));

    let body_bytes = res.into_body().collect().await.unwrap().to_bytes();
    let health: HealthResponse = serde_json::from_slice(&body_bytes).unwrap();

    assert_eq!(health.status, "ok");
    assert_eq!(health.service, "flightreader-server");
    assert_eq!(health.app, "flightreader-server");
    assert!(!health.has_flight_data);
    assert_eq!(health.point_count, 0);
}

#[tokio::test]
async fn test_health_endpoint_returns_ok_populated() {
    let state = AppState::new_with_dataset(mock_flight_dataset());
    let app = build_app(state);

    let req = Request::builder()
        .method("GET")
        .uri("/api/v1/health")
        .body(Body::empty())
        .unwrap();

    let res = app.oneshot(req).await.unwrap();
    assert_eq!(res.status(), StatusCode::OK);

    let body_bytes = res.into_body().collect().await.unwrap().to_bytes();
    let health: HealthResponse = serde_json::from_slice(&body_bytes).unwrap();

    assert_eq!(health.status, "ok");
    assert!(health.has_flight_data);
    assert_eq!(health.point_count, 600);
}

