#[tokio::test]
async fn test_flight_info_uninitialized() {
    let state = AppState::new_empty();
    let app = build_app(state);

    let req = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/info")
        .body(Body::empty())
        .unwrap();

    let res = app.oneshot(req).await.unwrap();
    assert_eq!(res.status(), StatusCode::OK);

    let body_bytes = res.into_body().collect().await.unwrap().to_bytes();
    let info: FlightInfoResponse = serde_json::from_slice(&body_bytes).unwrap();

    assert!(!info.loaded);
    assert_eq!(info.metadata.log_type, "NONE");
    assert_eq!(info.metadata.total_records, 0);
    assert!(info.bounds.is_none());
    assert!(info.events.is_none());
}

#[tokio::test]
async fn test_flight_info_populated() {
    let state = AppState::new_with_dataset(mock_flight_dataset());
    let app = build_app(state);

    let req = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/info")
        .body(Body::empty())
        .unwrap();

    let res = app.oneshot(req).await.unwrap();
    assert_eq!(res.status(), StatusCode::OK);

    let body_bytes = res.into_body().collect().await.unwrap().to_bytes();
    let info: FlightInfoResponse = serde_json::from_slice(&body_bytes).unwrap();

    assert!(info.loaded);
    assert_eq!(info.metadata.total_records, 600);
    assert_eq!(info.metadata.aircraft_model.as_deref(), Some("DJI Mavic 3"));

    // Verify spatial bounding box computation
    let bounds = info.bounds.expect("Bounds must be calculated for valid points");
    assert!(bounds.min_latitude <= bounds.max_latitude);
    assert!(bounds.min_longitude <= bounds.max_longitude);
    assert!(bounds.min_altitude_msl <= bounds.max_altitude_msl);

    // Verify events
    let events = info.events.expect("Events must be present");
    assert_eq!(events.len(), 2);
    assert_eq!(events[0].event_type, FlightEventType::HomeRecorded);
    assert_eq!(events[1].event_type, FlightEventType::Takeoff);
}

