#[tokio::test]
async fn test_flight_points_decimation_and_filtering() {
    let state = AppState::new_with_dataset(mock_flight_dataset());
    let app = build_app(state);

    // 1. Decimate 10 Hz down to 1 Hz (expect ~60 points out of 600)
    let req = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/points?rate=1.0")
        .body(Body::empty())
        .unwrap();

    let res = app.clone().oneshot(req).await.unwrap();
    assert_eq!(res.status(), StatusCode::OK);
    let body_bytes = res.into_body().collect().await.unwrap().to_bytes();
    let pts: ColumnarPointsResponse = serde_json::from_slice(&body_bytes).unwrap();
    assert!(pts.count >= 58 && pts.count <= 62, "Decimated count must be ~60, got {}", pts.count);
    assert_eq!(pts.latitudes.len(), pts.count);
    assert_eq!(pts.battery_pcts.len(), pts.count);

    // 2. Time-window filtering: between 10.0s and 20.0s
    let req = Request::builder()
        .method("GET")
        .uri("/api/v1/flight/points?start=10.0&end=20.0")
        .body(Body::empty())
        .unwrap();

    let res = app.oneshot(req).await.unwrap();
    assert_eq!(res.status(), StatusCode::OK);
