#[tokio::test]
async fn test_ws_scrubber_seek_synchronization() {
    let dataset = mock_flight_dataset();
    let state = AppState::new_with_dataset(dataset);
    let app = build_app(state);

    // Bind real OS-allocated loopback TCP socket
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();

    let server_task = tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });

    let ws_url = format!("ws://{}/api/v1/ws", addr);
    let (mut ws_stream, _) = connect_async(&ws_url)
        .await
        .expect("WebSocket handshake failed");

    // 1. Send Ping command
    ws_stream
        .send(Message::Text(r#"{"type":"ping"}"#.into()))
        .await
        .unwrap();

    let pong_msg = ws_stream
        .next()
        .await
        .expect("Expected WebSocket message")
        .expect("WebSocket read error");

    let pong_text = pong_msg.to_text().unwrap();
    let pong_server: WsServerMessage = serde_json::from_str(pong_text).unwrap();
    assert_eq!(pong_server, WsServerMessage::Pong);

    // 2. Send Seek to index 42
    ws_stream
        .send(Message::Text(r#"{"type":"seek","index":42}"#.into()))
        .await
        .unwrap();

    let frame_msg = ws_stream
        .next()
        .await
        .expect("Expected frame message")
        .expect("WebSocket read error");

    let frame_text = frame_msg.to_text().unwrap();
    let frame_server: WsServerMessage = serde_json::from_str(frame_text).unwrap();

    match frame_server {
        WsServerMessage::Frame(frame) => {
            assert_eq!(frame.index, 42);
            assert!((frame.elapsed_s - 4.2).abs() < 1e-4);
            assert_eq!(frame.gps_satellites, 18);
            assert_eq!(frame.flight_mode, "P-GPS");
            assert_eq!(frame.cell_voltages_mv.len(), 4);
        }
        other => panic!("Expected WsServerMessage::Frame, got {:?}", other),
    }

    // 3. Send Seek beyond max index (e.g. 9999) -> must clamp to index 599
    ws_stream
        .send(Message::Text(r#"{"type":"seek","index":9999}"#.into()))
        .await
        .unwrap();

    let clamped_msg = ws_stream
        .next()
        .await
        .expect("Expected clamped frame message")
        .expect("WebSocket read error");

    let clamped_server: WsServerMessage = serde_json::from_str(clamped_msg.to_text().unwrap()).unwrap();
    match clamped_server {
        WsServerMessage::Frame(frame) => {
            assert_eq!(frame.index, 599, "Seek index must be clamped to dataset maximum (599)");
        }
        other => panic!("Expected WsServerMessage::Frame, got {:?}", other),
    }

    // 4. Send Playback sync event
    ws_stream
        .send(Message::Text(
            r#"{"type":"playback","playing":true,"speed":2.0,"current_index":120}"#.into(),
        ))
        .await
        .unwrap();

    let pb_msg = ws_stream
        .next()
        .await
        .expect("Expected playback sync message")
        .expect("WebSocket read error");

    let pb_server: WsServerMessage = serde_json::from_str(pb_msg.to_text().unwrap()).unwrap();
    match pb_server {
        WsServerMessage::Playback {
            playing,
            speed,
            current_index,
        } => {
            assert!(playing);
            assert_eq!(speed, 2.0);
            assert_eq!(current_index, 120);
        }
        other => panic!("Expected WsServerMessage::Playback, got {:?}", other),
    }

    server_task.abort();
}

