// 7. Air-Gap & Zero Cloud Call Integrity Audit
// ============================================================================

#[test]
fn test_zero_cloud_call_audit() {
    // Audit every single compile-time embedded static asset in the binary.
    // Confirms 100% air-gap compliance with zero external CDN/font/analytics links.
    let banned_tokens = [
        "http://",
        "https://",
        "googleapis.com",
        "gstatic.com",
        "cloudflare.com",
        "jsdelivr.net",
        "unpkg.com",
        "mapbox.com",
        "tile.openstreetmap.org",
        "google-analytics.com",
    ];

    let mut asset_count = 0;
    for file in EmbeddedAssets::iter() {
        asset_count += 1;
        let content = EmbeddedAssets::get(&file).unwrap();
        let text = std::str::from_utf8(&content.data).unwrap_or("");

        for &banned in &banned_tokens {
            assert!(
                !text.contains(banned),
                "AIR-GAP VIOLATION: embedded asset '{}' contains prohibited cloud URL '{}'",
                file.as_ref(),
                banned
            );
        }
    }

    assert!(
        asset_count >= 10,
        "Expected at least 10 embedded assets, found {}",
        asset_count
    );
}

